checks.command:
d=$(mktemp -d) && cp -r . "$d" && cd "$d" && python3 -c "import re; p='src/lib.rs'; s=open(p).read(); s=s.replace('	pub authority: Address,
	/// The current count.
	pub count: u64,', '	pub count: u64,
	/// Placeholder doc.
	pub authority: Address,'); open(p, 'w').write(s)" && pina migrations create >/dev/null && printf 'pub(crate) const SOURCE_SIZE: usize = 42;
pub(crate) const DESTINATION_SIZE: usize = 42;
pub(crate) const WORKING_SIZE: usize = 42;
pub(crate) fn migrate(data: &mut [u8]) {
	let _ = data;
}
' > migrations/transitions/account_1_01/v0_to_v1.rs && pina migrations create >/dev/null && python3 -c "p='src/lib.rs'; s=open(p).read(); s=s.replace('	pub count: u64,', '	pub count: u64,
	/// Revision.
	pub revision: u32,', 1); open(p, 'w').write(s)" && pina migrations create && test -f migrations/transitions/account_1_01/v0_to_v1.rs.stale && ! pina migrations check
